<script setup lang="ts">
import QualificationWarnings from './QualificationWarnings.vue';
import {ref,onMounted} from 'vue';import {onShow} from '@dcloudio/uni-app';import BaseCard from '@/components/BaseCard.vue';import AppButton from '@/components/AppButton.vue';import SectionHeader from '@/components/SectionHeader.vue';import StatusTag from '@/components/StatusTag.vue';import AppIcon from '@/components/AppIcon.vue';import Stage1Status from './Stage1Status.vue';import {useStage1Page} from '../../services/use-stage1-page';import {stage1Service,label} from '../../services/stage1';import type {Data} from '../../services/stage1'
const props=defineProps<{profile?:boolean}>(),p=useStage1Page('home'),{error,loading}=p,summary=ref<Data|null>(null)
const entries=[{title:'商户资料',icon:'shop',action:'profile.read',path:'/pages/profile/basic/index'},{title:'资质与续期',icon:'bill',action:'profile.read',path:'/pages/qualifications/index'},{title:'工作人员',icon:'neighbor',action:'staff.manage',path:'/pages/staff/index'},{title:'合作协议与规则',icon:'bill',action:'cooperation.read',path:'/pages/cooperation/status/index'},{title:'经营资格',icon:'verified',action:'summary.read',path:'/pages/qualification/status/index'},{title:'履约设置与点位',icon:'location',action:'fulfillment.read',path:'/pages/fulfillment/index'}]
const counters=[{key:'pending',title:'待审核商品',filter:'status=SUBMITTED'},{key:'rejected',title:'已驳回商品',filter:'status=REJECTED'},{key:'logicallyListed',title:'逻辑上架',filter:'marketStatus=UPPER'},{key:'unlisted',title:'已下架',filter:'marketStatus=DOWN'},{key:'saleable',title:'当前可售',filter:'saleability=SALEABLE'},{key:'unavailable',title:'当前不可售',filter:'saleability=UNSALEABLE'},{key:'outOfStock',title:'缺货商品',filter:'stockState=OUT_OF_STOCK'},{key:'incomplete',title:'SKU资料不完整',filter:'stockState=INCOMPLETE'},{key:'restricted',title:'监管下架',filter:'forced=true'},{key:'draft',title:'商品草稿',filter:'status=DRAFT'},{key:'total',title:'全部商品',filter:''}]
function go(url:string){uni.navigateTo({url})}
function load(){return p.read(async()=>{if(props.profile||p.identity.state.identity?.identity!=='STORE')return null;return stage1Service.workbench()},v=>{summary.value=v})}
onMounted(load);onShow(load)
</script>
<template><view class="s1-home stack"><Stage1Status :error="error||p.authority.error"/><BaseCard v-if="p.applicant.value" class="s1-stack"><SectionHeader title="开始入驻"/><AppButton @click="go('/pages/onboarding/application/index')">填写或查看入驻申请</AppButton><AppButton variant="secondary" @click="go('/pages/invitations/accept/index')">接受工作人员邀请</AppButton></BaseCard><template v-if="p.authority.context"><BaseCard v-if="!profile" class="s1-stack"><SectionHeader :title="p.authority.context.storeName||'当前经营条件'"/><text v-if="p.authority.context.storeOperationalState==='CLOSED'" class="s1-meta">关闭原因：{{p.authority.context.closedReason||'请查看商户资料'}}。可按现有权限补正资料，新增经营受限。</text><StatusTag :tone="p.authority.context.storeOperationalState==='OPEN'?'success':'error'">{{label(p.authority.context.storeOperationalState)}}</StatusTag><template v-if="summary&&!error"><view class="s1-state"><text>基础经营</text><StatusTag :tone="summary.eligibility.BASIC_ELIGIBLE?'success':'pending'">{{summary.eligibility.BASIC_ELIGIBLE?'条件满足':'待完善'}}</StatusTag></view><view class="s1-state"><text>模拟 / 真实资格</text><text>{{summary.eligibility.MOCK_READY?'已就绪':'待完善'}} / {{summary.eligibility.REAL_READY?'已就绪':'待核验'}}</text></view><text class="s1-meta">更新于 {{summary.evaluatedAt}}</text><QualificationWarnings :items="summary.eligibility.qualificationWarnings"/></template><text v-else>经营状态统计{{loading?'读取中':'未知，请重新读取'}}。</text><AppButton variant="quiet" @click="go('/pages/qualification/status/index')">查看资格原因</AppButton></BaseCard><BaseCard v-if="!profile&&summary&&!error&&p.has('goods.read')"><SectionHeader title="商品待办"/><text class="s1-meta">按商品计数，卡片可交叉；当前可售按本环境模式计算，不能相加作为总数。</text><view class="s1-counts"><view v-for="item in counters" :key="item.key" class="s1-count" @click="go('/pages/operation/index?'+item.filter)"><text>{{item.title}}</text><text class="s1-number">{{summary.goods[item.key]}}</text></view></view></BaseCard><AppButton v-if="!profile&&p.has('goods.write')" @click="go('/pages/product/editor/index')">新增商品</AppButton><BaseCard><SectionHeader :title="profile?'商户服务':'常用入口'"/><view v-for="item in entries.filter(e=>p.has(e.action))" :key="item.path" class="s1-entry" @click="go(item.path)"><AppIcon :name="item.icon" :size="20"/><text>{{item.title}}</text><AppIcon name="chevron-right" :size="16"/></view></BaseCard></template><AppButton v-if="p.identity.state.sessionAvailable" variant="quiet" :loading="loading" @click="load">重新读取经营信息</AppButton></view></template>
<style scoped lang="scss">.s1-stack{display:flex;flex-direction:column;gap:$space-3}.s1-state{display:flex;flex-wrap:wrap;justify-content:space-between;gap:$space-2;font-size:15px}.s1-counts{display:grid;grid-template-columns:1fr 1fr;gap:$space-3}.s1-count{padding:$space-4;background:$color-group-bg;border-radius:$radius-md;display:flex;flex-direction:column;gap:$space-3;min-height:100px;font-size:15px}.s1-number{font-size:30px;font-weight:700;color:$color-primary}.s1-meta{color:$color-text-secondary;font-size:12px;overflow-wrap:anywhere}.s1-entry{display:flex;align-items:center;gap:$space-3;min-height:52px;border-bottom:1px solid $color-border;font-size:15px}.s1-entry>text{flex:1;min-width:0;overflow-wrap:anywhere}</style>
